    /* ServiceLevel */
    UA_CallbackValueSource serviceLevel = {readServiceLevel, NULL};
    retVal |= setVariableNode_callbackValueSource(server, UA_NS0ID(SERVER_SERVICELEVEL), serviceLevel);

    /* Auditing */
    UA_CallbackValueSource auditing = {readAuditing, NULL};
